//! Shared reward change: legacy integer/manual/immediate routes and visible boosts.
use gielinor_world::{assembly::{Job,Recipe,PreciseRecipe,Outcome},inventory::{Inventory,Item,StackType,Catalog},stats::Stats,npc::RandomSource,simulation::{World,PlayerData,WorldEvent},held_use::{Handler,Scope,Type,Request},CoordGrid};
struct NoDraw;impl RandomSource for NoDraw{fn below(&mut self,_:u32)->u32{panic!("assembly unexpectedly drew RNG")}}
fn fixture()->(Inventory,Stats){let mut inv=Inventory::new(28,StackType::Normal,false);for s in 0..28{inv.restore_slot(s,Some(Item{id:1931,count:1,vars:0})).unwrap();}for(s,id)in[(5,10),(19,11),(21,11),(23,10)]{inv.restore_slot(s,Some(Item{id,count:1,vars:0})).unwrap();}let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(12,99);stats.set_current(12,99);stats.set_fine_xp(12,130344311).unwrap();(inv,stats)}
fn expected(inv:&Inventory,out:i32)->Inventory{let mut n=inv.clone();n.restore_slot(5,Some(Item{id:out,count:1,vars:0})).unwrap();n.restore_slot(19,None).unwrap();n}
fn recipe(xp:u16)->Recipe{Recipe{first:10,second:11,output:12,skill:12,level:1,base_xp:xp,members:false}}
#[test]
fn sixteen_integer_api_controls_match_independent_awards_and_precise_equivalents(){let mut n=0;for xp in[0,2,15,50]{for rate in[0,100,125,500]{let(inv,stats)=fixture();let(mut a,mut x)=(inv.clone(),stats.clone());let(mut b,mut y)=(inv.clone(),stats.clone());let job=Job{recipe:recipe(xp),first_slot:5,second_slot:19};let old=job.complete_awarding(&mut a,&Catalog::default(),&mut x,rate,false);let precise=job.complete_awarding_tenths(&mut b,&Catalog::default(),&mut y,rate,false,xp*10);assert_eq!(old.0,precise.0);assert_eq!(old.1.is_some(),precise.1.is_some());assert_eq!((&a,&x),(&b,&y));if xp==0 || rate>0{assert_eq!(old.0,Outcome::Made);assert_eq!(a,expected(&inv,12));let mut e=stats.clone();e.set_fine_xp(12,130344311+i32::from(xp)*10*rate/100).unwrap();assert_eq!(x,e);assert_eq!(old.1.is_some(),xp>0);}else{assert_eq!(old.0,Outcome::InvalidReward);assert!(old.1.is_none());assert_eq!((a,x),(inv,stats));}n+=1;}}assert_eq!(n,16);}
#[test]
fn ninety_six_legacy_held_routes_keep_immediate_and_queued_publication(){let mut n=0;for kind in 0..3{for reverse in[false,true]{for xp in[0,2,15,50]{for rate in[0,100,125,500]{let r=recipe(xp);let(inv,stats)=fixture();let mut w=World::default();w.collision.allocate(3200,3200,0);let mut d=PlayerData::new(1,"Independent legacy assembly".into(),CoordGrid::new(3200,3200,0).unwrap(),stats.clone());d.inventory=inv.clone();d.xp_rate_hundreds=rate;w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();for id in[10,11]{w.held_use_types.insert(id,Type{id,content:-1});}let h=match kind{0=>Handler::Assembly(r),1=>Handler::AssemblyTimed{recipe:r,ticks:4},_=>Handler::AssemblyImmediate(r)};w.held_use_handlers.register(Scope::Types,10,11,h).unwrap();w.drain_events();let h=if reverse{Request{selected_slot:19,selected_id:11,target_slot:5,target_id:10}}else{Request{selected_slot:5,selected_id:10,target_slot:19,target_id:11}};w.prepare_held_use(a,h).unwrap();w.finish_held_use(a,h).unwrap();let good=xp==0 || rate>0;let mut e=stats.clone();if good{e.set_fine_xp(12,130344311+i32::from(xp)*10*rate/100).unwrap();}let ei=if good{expected(&inv,12)}else{inv.clone()};if kind==2{assert_eq!(w.data(a).unwrap().inventory,ei);assert_eq!(w.data(a).unwrap().stats,e);}else{for _ in 0..if kind==0{2}else{4}{w.tick_with_random(&mut NoDraw).unwrap();assert_eq!(w.data(a).unwrap().inventory,inv);assert_eq!(w.data(a).unwrap().stats,stats);}w.tick_with_random(&mut NoDraw).unwrap();}for _ in 0..6{w.tick_with_random(&mut NoDraw).unwrap();}assert_eq!(w.data(a).unwrap().inventory,ei);assert_eq!(w.data(a).unwrap().stats,e);assert_eq!(w.drain_events().iter().filter(|e|matches!(e,WorldEvent::SkillAdvanced{..})).count(),usize::from(good && xp>0));n+=1;}}}}assert_eq!(n,96);}
fn fine_at(level:u8)->i32{let sum:i32=(1..level).map(|l|(f64::from(l)+300.0*2f64.powf(f64::from(l)/7.0)).floor() as i32).sum();sum/4*10}
#[test]
fn sixteen_boosted_current_level_precise_transactions_ignore_base_requirement(){let mut n=0;for(orb,out,level,xp)in[(571,1395,54,1000),(575,1399,58,1125),(569,1393,62,1250),(573,1397,66,1375)]{for rate in[0,100,125,500]{let(mut inv,mut stats)=fixture();inv.restore_slot(5,Some(Item{id:1391,count:1,vars:0})).unwrap();inv.restore_slot(19,Some(Item{id:orb,count:1,vars:0})).unwrap();stats.set_base(12,level-1);stats.set_current(12,level);stats.set_fine_xp(12,fine_at((level-1) as u8)).unwrap();let before=(inv.clone(),stats.clone());let r=PreciseRecipe{recipe:Recipe{first:1391,second:orb,output:out,skill:12,level:level as u8,base_xp:0,members:true},xp_tenths:xp,ticks:2,animation:Some(7531),spot:None};let(result,advanced)=Job{recipe:r.recipe,first_slot:5,second_slot:19}.complete_awarding_tenths(&mut inv,&Catalog::default(),&mut stats,rate,true,xp);if rate>0{assert_eq!(result,Outcome::Made);assert!(advanced.is_some());let mut e=before.1.clone();e.set_fine_xp(12,e.fine_xp(12)+i32::from(xp)*rate/100).unwrap();assert_eq!(stats,e);assert_eq!(inv,expected(&before.0,out));}else{assert_eq!(result,Outcome::InvalidReward);assert_eq!((inv,stats),before);}n+=1;}}assert_eq!(n,16);}
